<?php require __DIR__.'/../app/bootstrap.php';$u=user();$total=$pdo->query("SELECT COUNT(*) FROM tickets")->fetchColumn();$active=$pdo->query("SELECT COUNT(*) FROM tickets WHERE status NOT IN('Selesai','Diambil','Dibatalkan')")->fetchColumn();$done=$pdo->query("SELECT COUNT(*) FROM tickets WHERE status='Selesai' AND MONTH(received_at)=MONTH(CURRENT_DATE()) AND YEAR(received_at)=YEAR(CURRENT_DATE())")->fetchColumn();$rev=$pdo->query("SELECT COALESCE(SUM(final_cost),0) FROM tickets")->fetchColumn();$rows=$pdo->query("SELECT t.ticket_no,c.name,t.device,t.status,t.final_cost FROM tickets t JOIN customers c ON c.id=t.customer_id ORDER BY t.id DESC LIMIT 10")->fetchAll();?><!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Dashboard</title><style>body{font:14px Arial;background:#f5f7fb;margin:0;color:#172033}.top{background:#111827;color:#fff;padding:16px 24px}.top a{color:#fff;margin-left:14px}.wrap{max-width:1200px;margin:25px auto;padding:0 15px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.card{background:#fff;padding:18px;border:1px solid #e5e7eb;border-radius:12px;margin-top:15px}.card b{font-size:25px;display:block;margin-top:7px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left;font-size:12px}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}}</style><div class=top><b>🔧 ServisPro</b><span style=float:right><?=e($u['name'])?> · <a href=tickets.php>Tiket</a><a href=customers.php>Pelanggan</a><a href=parts.php>Sparepart</a><a href=payments.php>Pembayaran</a><a href=logout.php>Keluar</a></span></div><div class=wrap><h2>Dashboard</h2><div class=cards><div class=card>Total Tiket<b><?=$total?></b></div><div class=card>Sedang Diproses<b><?=$active?></b></div><div class=card>Selesai Bulan Ini<b><?=$done?></b></div><div class=card>Pendapatan<b>Rp<?=number_format($rev,0,',','.')?></b></div></div><div class=card><h3>Servis Terbaru</h3><table><tr><th>ID</th><th>Pelanggan</th><th>Perangkat</th><th>Status</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['ticket_no'])?></td><td><?=e($r['name'])?></td><td><?=e($r['device'])?></td><td><?=e($r['status'])?></td><td>Rp<?=number_format($r['final_cost'],0,',','.')?></td></tr><?php endforeach;?></table></div></div>